SELECT *, LEAD(discount_pct, 1) OVER (PARTITION BY channel ORDER BY ends_on, id) AS next_discount_pct, AVG(discount_pct) OVER (PARTITION BY channel, promo_code ORDER BY starts_on, id ROWS BETWEEN 5 PRECEDING AND 1 PRECEDING) AS discount_pct_avg_5_prior, LAST_VALUE(channel) IGNORE NULLS OVER (PARTITION BY promo_code, channel ORDER BY starts_on, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_channel, AVG(discount_pct) OVER (PARTITION BY channel) AS channel_avg_discount_pct, FIRST_VALUE(channel, TRUE) OVER (PARTITION BY channel, promo_code ORDER BY starts_on, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_channel FROM promotions
